import { useEffect, useMemo, useState } from 'react';
import { productApi } from '../services/api';
import ProductCard from './ProductCard';
import './ProductList.css';

const SORT_OPTIONS = [
  { value: 'relevance', label: 'Most relevant' },
  { value: 'price-low', label: 'Price low to high' },
  { value: 'price-high', label: 'Price high to low' },
  { value: 'rating', label: 'Highest rating' },
  { value: 'reviews', label: 'Most reviews' },
];

const CATEGORY_OPTIONS = ['all', 'Mobiles', 'Laptops', 'Computer Hardware', 'Gaming', 'Accessories', 'Smart Devices', 'Technology'];

function ProductSkeletonGrid() {
  return (
    <div className="product-grid">
      {Array.from({ length: 8 }).map((_, index) => (
        <div className="product-skeleton" key={index}>
          <div className="loading-skeleton image" />
          <div className="loading-skeleton line wide" />
          <div className="loading-skeleton line" />
          <div className="loading-skeleton line small" />
        </div>
      ))}
    </div>
  );
}

function ProductList({ initialSearch = '', initialCategory = 'all', headline = 'Live Product Search' }) {
  const [query, setQuery] = useState(initialSearch);
  const [submittedQuery, setSubmittedQuery] = useState(initialSearch || 'laptop');
  const [category, setCategory] = useState(initialCategory || 'all');
  const [brand, setBrand] = useState('all');
  const [minPrice, setMinPrice] = useState('');
  const [maxPrice, setMaxPrice] = useState('');
  const [sort, setSort] = useState('relevance');
  const [products, setProducts] = useState([]);
  const [providerInfo, setProviderInfo] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    setQuery(initialSearch);
    setSubmittedQuery(initialSearch || 'laptop');
  }, [initialSearch]);

  useEffect(() => {
    setCategory(initialCategory || 'all');
  }, [initialCategory]);

  const params = useMemo(
    () => ({ q: submittedQuery, category, brand, minPrice, maxPrice, sort, limit: 32 }),
    [submittedQuery, category, brand, minPrice, maxPrice, sort]
  );

  useEffect(() => {
    let active = true;
    setLoading(true);
    setError('');
    productApi
      .searchProducts(params)
      .then((data) => {
        if (!active) return;
        setProducts(data.products || []);
        setProviderInfo(data);
      })
      .catch((err) => {
        if (!active) return;
        setError(err.response?.data?.message || 'Unable to fetch live products. Please check backend server and API keys.');
      })
      .finally(() => active && setLoading(false));
    return () => {
      active = false;
    };
  }, [params]);

  const submitSearch = (event) => {
    event.preventDefault();
    setSubmittedQuery(query.trim() || 'laptop');
  };

  return (
    <section className="products-section">
      <div className="section-header">
        <div>
          <span className="eyebrow">Real-time API products</span>
          <h1 className="title">{headline}</h1>
          <p className="subtitle">
            Search any tech product. The backend aggregates external providers, normalizes product data, caches results,
            and sends clean JSON to the React frontend.
          </p>
        </div>
        <span className="badge">{products.length} results</span>
      </div>

      <form className="big-search" onSubmit={submitSearch}>
        <input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder="Search iPhone 17 Pro Max, Samsung Galaxy S26, RTX 5090..."
        />
        <button className="btn btn-primary" type="submit">Search live</button>
      </form>

      <div className="product-layout">
        <aside className="filter-panel card">
          <h3>Filters</h3>
          <label>
            Category
            <select value={category} onChange={(event) => setCategory(event.target.value)}>
              {CATEGORY_OPTIONS.map((item) => <option key={item} value={item}>{item === 'all' ? 'All categories' : item}</option>)}
            </select>
          </label>
          <label>
            Brand
            <input value={brand === 'all' ? '' : brand} onChange={(event) => setBrand(event.target.value || 'all')} placeholder="Apple, Samsung, NVIDIA" />
          </label>
          <label>
            Minimum price
            <input type="number" value={minPrice} onChange={(event) => setMinPrice(event.target.value)} placeholder="0" />
          </label>
          <label>
            Maximum price
            <input type="number" value={maxPrice} onChange={(event) => setMaxPrice(event.target.value)} placeholder="5000" />
          </label>
          <label>
            Sort by
            <select value={sort} onChange={(event) => setSort(event.target.value)}>
              {SORT_OPTIONS.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}
            </select>
          </label>
          <button className="btn btn-secondary" onClick={() => { setCategory('all'); setBrand('all'); setMinPrice(''); setMaxPrice(''); setSort('relevance'); }} type="button">
            Reset filters
          </button>
        </aside>

        <div className="product-results">
          <div className="results-topbar card">
            <div>
              <strong>{submittedQuery}</strong>
              <span> Cache: {providerInfo?.cache || 'checking'} · Providers: {(providerInfo?.providersUsed || []).join(', ') || 'loading'}</span>
            </div>
            {providerInfo?.notice && <small>{providerInfo.notice}</small>}
          </div>

          {loading && <ProductSkeletonGrid />}
          {!loading && error && <div className="empty-state"><h3>Search failed</h3><p>{error}</p></div>}
          {!loading && !error && products.length === 0 && (
            <div className="empty-state">
              <h3>No products found</h3>
              <p>Try a broader keyword such as laptop, smartphone, RTX GPU, gaming console, or headphones.</p>
            </div>
          )}
          {!loading && !error && products.length > 0 && (
            <div className="product-grid">
              {products.map((product) => <ProductCard key={product.id || product.productId} product={product} />)}
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

export default ProductList;
